(function(){
'use strict';
const STAGES=['New','Screening','Shortlisted','Interview','Reference checks','Offer','Hired','Rejected','Withdrawn'];
const stageLabel=stage=>stage==='Rejected'?'Not Shortlisted':stage;
const CRITERIA={role_skills:'Role-specific skills',relevant_experience:'Relevant experience',communication:'Communication for this role',problem_solving:'Problem-solving'};
const esc=window.CAGE_JOB_ADVERT.esc,api=()=>window.CAGE_BACKEND;
const dialog=document.createElement('dialog');dialog.id='applicant-review-dialog';dialog.className='app-dialog applicant-review-dialog';dialog.setAttribute('aria-labelledby','applicant-review-title');
dialog.innerHTML=`<header class="review-header"><div><p class="section-kicker">Recruitment review · Private to recruitment staff</p><h2 id="applicant-review-title">Applicant review</h2><p id="applicant-review-subtitle"></p></div><button type="button" class="icon-button" id="review-close" aria-label="Close applicant review">×</button></header><div class="review-tools"><p id="review-current"></p><button type="button" class="secondary-button" id="review-reload">Reload review</button></div><p id="review-status" role="status" aria-live="polite"></p><p id="review-error" role="alert" tabindex="-1"></p><div id="review-content" hidden><details class="review-application-details"><summary>Application details</summary><div id="review-application-copy"></div></details><div class="review-layout"><section class="review-compose"><h3>Record your review</h3><p>Use evidence relevant to this vacancy. Notes and scorecards are added to the history.</p><form id="applicant-review-form" novalidate><label class="field"><span>Review action</span><select name="action"><option value="note">Add a review note</option><option value="assessment">Record a scorecard</option><option value="stage">Change application stage</option><option value="assignment">Assign a reviewer</option></select></label><div data-review-action="assessment" hidden><p class="review-rubric">Score each criterion against this role: 1 = limited evidence, 2 = some evidence, 3 = meets requirements, 4 = strong evidence, 5 = exceptional evidence. Add a note if more information is needed before scoring.</p>${Object.entries(CRITERIA).map(([key,label])=>`<label class="review-score-field"><span>${label}</span><select name="${key}" aria-label="${label}"><option value="">Not scored</option>${[1,2,3,4,5].map(n=>`<option value="${n}">${n}</option>`).join('')}</select></label>`).join('')}<p id="review-score-total"></p></div><label class="field" data-review-action="stage" hidden><span>Move to stage</span><select name="stage">${STAGES.map(x=>`<option value="${esc(x)}">${esc(stageLabel(x))}</option>`).join('')}</select><small>This records your decision. Offer letters are handled separately.</small></label><label class="field" data-review-action="assignment" hidden><span>Responsible reviewer</span><select name="reviewer"></select></label><label class="field"><span id="review-notes-label">Review note *</span><textarea name="notes" rows="6" maxlength="5000" placeholder="Record the evidence and your reasoning."></textarea><small>Up to 5,000 characters. Include only information relevant to the recruitment decision.</small></label><button type="submit" class="primary-button" id="review-save">Save review</button></form></section><section class="review-record"><h3>Latest scorecards</h3><div id="review-assessments"></div><h3>Decision and review history</h3><p class="review-history-help">Each entry records the author and time. Earlier decisions made before this feature have no recorded history.</p><div id="review-history"></div><button type="button" class="secondary-button" id="review-more" hidden>Load older entries</button></section></div></div>`;
document.body.append(dialog);
const form=dialog.querySelector('form'),error=dialog.querySelector('#review-error'),status=dialog.querySelector('#review-status'),content=dialog.querySelector('#review-content');
let context=null,applicationId=null,owner=null,opener=null,generation=0,busy=false,loading=false,pendingRequest=null,nextBefore=null;
function date(value){return new Date(value).toLocaleString('en-GB',{dateStyle:'medium',timeStyle:'short',timeZone:'Africa/Blantyre'});}
function total(scores){return Object.keys(CRITERIA).reduce((sum,key)=>sum+Number(scores[key]||0),0);}
function controls(){form.querySelectorAll('input,textarea,select,button').forEach(x=>x.disabled=busy||loading||!context?.can_edit);dialog.querySelector('#review-reload').disabled=busy||loading;dialog.querySelector('#review-close').disabled=busy;}
function actionFields(){const action=form.elements.action.value;dialog.querySelectorAll('[data-review-action]').forEach(el=>el.hidden=el.dataset.reviewAction!==action);dialog.querySelector('#review-notes-label').textContent=action==='assignment'?'Assignment note (optional)':action==='stage'?'Reason for this decision *':action==='assessment'?'Evidence supporting these scores *':'Review note *';const scores=Object.fromEntries(Object.keys(CRITERIA).map(key=>[key,form.elements[key].value]));dialog.querySelector('#review-score-total').textContent=Object.values(scores).every(Boolean)?`Your score: ${total(scores)} / 20`:'Complete all four criteria to record a scorecard.';}
function historyHtml(events){return events.map(e=>`<article class="review-event"><div><strong>${esc(e.kind==='stage'?`${stageLabel(e.from_stage)} → ${stageLabel(e.to_stage)}`:e.kind==='assignment'?`${e.from_reviewer_name||'Unassigned'} → ${e.to_reviewer_name||'Unassigned'}`:e.kind==='assessment'?`Scorecard · ${total(e.scores)} / 20`:'Review note')}</strong><small>${esc(e.actor_name)} · ${esc(date(e.created_at))} (Malawi)</small></div>${e.kind==='assessment'?`<dl class="review-score-list">${Object.entries(CRITERIA).map(([key,label])=>`<dt>${label}</dt><dd>${esc(e.scores[key])} / 5</dd>`).join('')}</dl>`:''}<p>${esc(e.notes)}</p></article>`).join('');}
function draw(data){
 context=data;nextBefore=data.next_before;
 dialog.querySelector('#applicant-review-title').textContent=data.application.full_name;
 dialog.querySelector('#applicant-review-subtitle').textContent=data.vacancy||'Vacancy';
 dialog.querySelector('#review-current').textContent=`${stageLabel(data.application.stage)} · Reviewer: ${data.assigned_reviewer_name||'Unassigned'}`;
 const select=form.elements.reviewer;select.innerHTML='<option value="">Unassigned</option>'+data.reviewers.map(p=>`<option value="${esc(p.id)}">${esc(p.name)}</option>`).join('');
 if(data.application.assigned_reviewer&&!data.reviewers.some(p=>p.id===data.application.assigned_reviewer))select.innerHTML+=`<option value="${esc(data.application.assigned_reviewer)}" disabled>${esc(data.assigned_reviewer_name||'Previously assigned reviewer')} (inactive)</option>`;
 select.value=data.application.assigned_reviewer||'';form.elements.stage.value=data.application.stage;
 const legacy=data.application.legacy_notes?`<details><summary>Earlier screening note · author/date not recorded</summary><p>${esc(data.application.legacy_notes)}</p></details>`:'';
 dialog.querySelector('#review-assessments').innerHTML=data.assessments.length?data.assessments.map(e=>`<article class="review-assessment"><strong>${esc(e.actor_name)} · ${total(e.scores)} / 20</strong><small>${esc(date(e.created_at))} (Malawi)</small><dl class="review-score-list">${Object.entries(CRITERIA).map(([key,label])=>`<dt>${label}</dt><dd>${esc(e.scores[key])} / 5</dd>`).join('')}</dl><p>${esc(e.notes)}</p></article>`).join(''):'<p class="review-empty">No scorecards recorded. Reviewers make the hiring decision; scores support their judgment.</p>';
 dialog.querySelector('#review-history').innerHTML=legacy+(data.history.length?historyHtml(data.history):'<p class="review-empty">No review entries yet.</p>');dialog.querySelector('#review-more').hidden=!nextBefore;
 const applicant=window.CAGE_HR_UI.application(applicationId);dialog.querySelector('#review-application-copy').innerHTML=applicant?`<p><strong>Cover note</strong></p><p>${esc(applicant.cover_note||'Not supplied')}</p>${(applicant.screening_answers||[]).map(x=>`<p><strong>${esc(x.question)}</strong></p><p>${esc(x.answer)}</p>`).join('')}<button type="button" class="secondary-button" id="review-open-cv">Open CV</button>`:'';
 content.hidden=false;actionFields();controls();
}
async function refresh(preserve=true){
 if(loading||busy)return;const token=generation,uid=owner;loading=true;controls();error.textContent='';status.textContent='Loading review…';
 try{const data=await api().applicationReviewRead(applicationId);if(token!==generation||uid!==api().currentProfile()?.id)return;if(!preserve)form.reset();draw(data);status.textContent=data.can_edit?'Review ready.':'You have read-only recruitment access.';}
 catch(e){if(token===generation){error.textContent=e.message||'Review could not be loaded. Use Reload review to try again.';status.textContent='';}}
 finally{if(token===generation){loading=false;controls();}}
}
async function open(id,button,stage=null){
 const profile=api().currentProfile();if(!profile||!['admin','manager','hr'].includes(profile.role))return;
 generation++;applicationId=id;owner=profile.id;opener=button;context=null;pendingRequest=null;nextBefore=null;loading=false;busy=false;form.reset();content.hidden=true;error.textContent='';status.textContent='';dialog.querySelector('#applicant-review-title').textContent='Applicant review';dialog.querySelector('#applicant-review-subtitle').textContent='';dialog.querySelector('#review-current').textContent='';
 if(!dialog.open)dialog.showModal();await refresh(false);
 if(stage&&context?.can_edit){form.elements.action.value='stage';form.elements.stage.value=stage;actionFields();form.elements.notes.focus();}
}
function close(){if(busy)return;generation++;loading=false;dialog.close();form.reset();content.hidden=true;context=null;pendingRequest=null;opener?.focus();}
dialog.querySelector('#review-close').addEventListener('click',close);dialog.addEventListener('cancel',e=>{e.preventDefault();close();});
dialog.querySelector('#review-reload').addEventListener('click',()=>refresh());
form.addEventListener('input',()=>{pendingRequest=null;actionFields();});form.addEventListener('change',()=>{pendingRequest=null;actionFields();});
dialog.addEventListener('click',e=>{if(e.target.closest('#review-open-cv')){const a=window.CAGE_HR_UI.application(applicationId);if(a)api().openFile(a.cv_storage_path).catch(e=>error.textContent=e.message);}});
dialog.querySelector('#review-more').addEventListener('click',async()=>{if(!nextBefore||loading||busy)return;const token=generation,before=nextBefore;const button=dialog.querySelector('#review-more');button.disabled=true;try{const older=await api().applicationReviewRead(applicationId,before);if(token!==generation)return;dialog.querySelector('#review-history').insertAdjacentHTML('beforeend',historyHtml(older.history));nextBefore=older.next_before;button.hidden=!nextBefore;}catch(e){if(token===generation)error.textContent=e.message||'Older entries could not be loaded.';}finally{button.disabled=false;}});
form.addEventListener('submit',async event=>{
 event.preventDefault();if(busy||loading||!context?.can_edit)return;error.textContent='';status.textContent='';
 const action=form.elements.action.value,notes=form.elements.notes.value.trim(),scores=Object.fromEntries(Object.keys(CRITERIA).map(key=>[key,Number(form.elements[key].value)]));
 if((action!=='assignment'&&!notes)||notes.length>5000){error.textContent='Provide a note or reason of up to 5,000 characters.';form.elements.notes.focus();return;}
 if(action==='assessment'&&Object.values(scores).some(value=>!Number.isInteger(value)||value<1||value>5)){error.textContent='Score all four criteria from 1 to 5, or add a note if you need more information.';return;}
 if(action==='stage'&&form.elements.stage.value===context.application.stage){error.textContent='Choose a different stage before saving your decision.';return;}
 const reviewer=form.elements.reviewer.value||null;if(action==='assignment'&&reviewer===(context.application.assigned_reviewer||null)){error.textContent='Choose a different reviewer or unassign the current reviewer.';return;}
 if(owner!==api().currentProfile()?.id){error.textContent='Your session changed. Reopen this review after signing in.';return;}
 const token=generation;pendingRequest ||= crypto.randomUUID();busy=true;controls();form.setAttribute('aria-busy','true');status.textContent='Saving review…';let saved=false;
 try{await api().applicationReviewWrite({p_application:applicationId,p_expected_version:context.application.review_version,p_action:action,p_notes:notes,p_scores:action==='assessment'?scores:{},p_stage:action==='stage'?form.elements.stage.value:null,p_reviewer:action==='assignment'?reviewer:null,p_request_id:pendingRequest});saved=true;}
 catch(e){if(token===generation){error.textContent=e.message||'Save could not be confirmed. Your text is kept; retrying the same save will not duplicate it.';status.textContent='';error.focus();}}
 finally{if(token===generation){busy=false;controls();form.removeAttribute('aria-busy');}}
 if(saved&&token===generation&&owner===api().currentProfile()?.id){form.elements.notes.value='';pendingRequest=null;Object.keys(CRITERIA).forEach(key=>form.elements[key].value='');status.textContent='Review saved.';await window.CAGE_HR_UI.load();await refresh();if(error.textContent)status.textContent='Your review was saved. Reload to see the latest history.';else status.textContent='Review saved. Latest history shown.';}
});
document.addEventListener('click',event=>{const button=event.target.closest('[data-review-candidate],[data-not-shortlisted]');if(button)open(button.dataset.reviewCandidate||button.dataset.notShortlisted,button,button.hasAttribute('data-not-shortlisted')?'Rejected':null);});
window.addEventListener('cage:session-ended',()=>{generation++;busy=false;loading=false;context=null;owner=null;applicationId=null;pendingRequest=null;form.reset();content.hidden=true;dialog.querySelector('#review-history').textContent='';dialog.querySelector('#review-assessments').textContent='';dialog.querySelector('#review-application-copy').textContent='';dialog.querySelector('#applicant-review-title').textContent='Applicant review';dialog.querySelector('#applicant-review-subtitle').textContent='';dialog.querySelector('#review-current').textContent='';status.textContent='';error.textContent='';if(dialog.open)dialog.close();});
window.CAGE_RECRUITMENT_REVIEWS={open};
})();
